const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app');
const state={center:null,fields:[],centers:[],managers:[],selectedField:null,selectedSlot:null,selectedDate:null,manager:null,adminStats:null,weekStart:null,calendarView:'week',calendarMonth:null,installPrompt:null};
const qs=new URLSearchParams(location.search), view=qs.get('view')||'home', centerSlug=qs.get('center')||'';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const money=c=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format((Number(c)||0)/100);
const isoDate=d=>{const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)};
const today=()=>isoDate(new Date());
const addDays=(s,n)=>{const d=new Date(`${s}T12:00:00`);d.setDate(d.getDate()+n);return isoDate(d)};
const prettyDate=s=>new Intl.DateTimeFormat('it-IT',{weekday:'short',day:'2-digit',month:'short'}).format(new Date(`${s}T12:00:00`));
const longDate=s=>new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long'}).format(new Date(`${s}T12:00:00`));
const locationLabel=a=>(a||'Centro sportivo').split(',')[0].trim();
const dayNames=['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'];

async function api(action,options={}){
  const headers=options.body instanceof FormData ? (options.headers||{}) : {'content-type':'application/json',...(options.headers||{})};
  const res=await fetch(`/api?action=${action}`,{credentials:'include',...options,headers});
  const data=await res.json().catch(()=>({ok:false,error:'Risposta non valida'}));
  if(!res.ok||data.ok===false)throw new Error(data.error||'Errore'); return data;
}
function toast(msg,type='ok'){const e=document.createElement('div');e.className=`notice toast ${type}`;e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),3300)}
function setAccent(c){document.documentElement.style.setProperty('--accent',c||'#101828');document.querySelector('meta[name=theme-color]')?.setAttribute('content',c||'#101828')}
function modal(html,cls=''){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card ${cls}">${html}</div>`;document.body.append(m);m.addEventListener('click',e=>{if(e.target===m)m.remove()});return m}
function sportList(c){return String(c.sports||'').split(',').map(x=>x.trim()).filter(Boolean)}
function fieldPrice(f,date=today()){
  const wk=[0,6].includes(new Date(`${date}T12:00:00`).getDay());
  return {base:wk&&Number(f.weekend_price_cents)>0?f.weekend_price_cents:f.price_cents,shower:wk&&Number(f.weekend_shower_price_cents)>0?f.weekend_shower_price_cents:f.shower_price_cents,weekend:wk};
}
function priceText(f,date=today()){const p=fieldPrice(f,date);return `${money(p.base)} / ${money(p.shower)} a persona`}
function mondayOf(s=today()){const d=new Date(`${s}T12:00:00`),day=d.getDay()||7;d.setDate(d.getDate()-day+1);return isoDate(d)}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;document.querySelectorAll('[data-install]').forEach(b=>b.classList.remove('hidden'))});
async function installApp(){if(!state.installPrompt)return toast('L’installazione sarà disponibile dal browser quando supportata','error');state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null}
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));

async function loadHome(){setAccent('#101828');const d=await api('public-centers');state.centers=d.centers||[];renderHome()}
function renderHome(){
  const locs=[...new Set(state.centers.map(c=>locationLabel(c.address)).filter(Boolean))].sort(), sports=[...new Set(state.centers.flatMap(sportList))].sort();
  app.innerHTML=`<main class="portal-shell">
    <header class="portal-header"><a class="portal-brand" href="/"><div class="portal-mark">S</div><div><strong>Sport Booking</strong><span>Prenota il tuo campo</span></div></a><div class="row"><button class="btn ghost hidden" data-install>Installa app</button><a class="btn ghost" href="/?view=login">Area riservata</a></div></header>
    <section class="portal-hero"><div class="hero-kicker">PRENOTAZIONI SPORTIVE</div><h1>Trova. Scegli.<br><span>Gioca.</span></h1><p>Centri sportivi, campi e orari disponibili in un’unica app.</p><div class="search-wrap"><span class="search-icon">⌕</span><input id="centerSearch" placeholder="Cerca centro, località o disciplina..." autocomplete="off"></div></section>
    <section class="portal-section"><div class="section-head premium-head"><div><span class="eyebrow">CENTRI DISPONIBILI</span><h2>Scegli dove giocare</h2></div><span class="counter" id="centerCount"></span></div>
      <div class="filter-bar"><select class="input compact-filter" id="locationFilter"><option value="">Tutte le località</option>${locs.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select class="input compact-filter" id="sportFilter"><option value="">Tutti gli sport</option>${sports.map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="btn small" id="clearFilters">Azzera filtri</button></div>
      <div id="centerGrid" class="center-grid"></div></section>
    <footer class="portal-footer"><span>Sport Booking</span><span>Prenotazioni semplici. Gestione centralizzata.</span></footer></main>`;
  const apply=()=>{const q=$('#centerSearch').value.trim().toLowerCase(),loc=$('#locationFilter').value,sport=$('#sportFilter').value;const list=state.centers.filter(c=>(!q||[c.name,c.address,c.sports,c.description].join(' ').toLowerCase().includes(q))&&(!loc||locationLabel(c.address)===loc)&&(!sport||sportList(c).includes(sport)));$('#centerGrid').innerHTML=centerCards(list);$('#centerCount').textContent=`${list.length} ${list.length===1?'centro':'centri'}`};
  $('#centerSearch').oninput=apply;$('#locationFilter').onchange=apply;$('#sportFilter').onchange=apply;$('#clearFilters').onclick=()=>{$('#centerSearch').value='';$('#locationFilter').value='';$('#sportFilter').value='';apply()};$$('[data-install]').forEach(b=>b.onclick=installApp);apply();
}
function centerCards(list){if(!list.length)return `<div class="empty premium-empty">Nessun centro corrisponde ai filtri.</div>`;return list.map(c=>`<a class="center-premium-card" href="/?center=${encodeURIComponent(c.slug)}"><div class="center-cover" ${c.cover_url?`style="background-image:url('${esc(c.cover_url)}')"`:''}><div class="center-cover-shade"></div><div class="location-badge">⌖ ${esc(locationLabel(c.address))}</div><div class="center-logo">${c.logo_url?`<img src="${esc(c.logo_url)}" alt="">`:'S'}</div></div><div class="center-card-body"><div class="center-card-title"><div><h3>${esc(c.name)}</h3><p>${esc(c.address||'')}</p></div><span class="arrow-circle">→</span></div><div class="center-meta"><span>${Number(c.fields_count||0)} ${Number(c.fields_count||0)===1?'campo':'campi'}</span>${sportList(c).slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></a>`).join('')}

async function loadPublic(){const d=await api(`center&slug=${encodeURIComponent(centerSlug)}`);state.center=d.center;state.fields=d.fields||[];setAccent(state.center.accent_color);renderPublic()}
function renderPublic(){const c=state.center, first=state.fields[0];state.selectedField=first||null;state.selectedDate=today();
  app.innerHTML=`<main class="center-app"><header class="center-topbar"><a class="back-home" href="/">← <span>Tutti i centri</span></a><div class="center-brand"><div class="logo">${c.logo_url?`<img src="${esc(c.logo_url)}">`:'S'}</div><div><strong>${esc(c.name)}</strong><span>${esc(locationLabel(c.address))}</span></div></div><button class="btn ghost hidden" data-install>Installa</button></header>
    <section class="center-hero" ${c.cover_url?`style="background-image:url('${esc(c.cover_url)}')"`:''}><div class="center-hero-overlay"></div><div class="center-hero-content"><span class="hero-chip">${esc(locationLabel(c.address))}</span><h1>${esc(c.name)}</h1><p>${esc(c.description||'Prenota il tuo campo in pochi secondi.')}</p><div class="hero-actions"><a class="btn light" href="#book">Prenota ora</a>${c.conventions_enabled?'<a class="btn glass" href="#conventions">Convenzioni</a>':''}</div></div></section>
    <section class="center-section"><div class="section-head premium-head"><div><span class="eyebrow">1 · SCEGLI IL CAMPO</span><h2>Campi disponibili</h2></div></div><div class="field-grid" id="fieldGrid">${fieldCards()}</div></section>
    <section class="booking-premium" id="book"><div class="booking-intro"><span class="eyebrow">2 · SCEGLI QUANDO</span><h2>Trova subito un orario</h2><p>Oggi, domani o una data a tua scelta. Gli slot occupati vengono esclusi automaticamente.</p></div><div class="booking-panel"><div class="quick-dates"><button class="date-chip active" data-date="${today()}">Oggi <small>${prettyDate(today())}</small></button><button class="date-chip" data-date="${addDays(today(),1)}">Domani <small>${prettyDate(addDays(today(),1))}</small></button><label class="date-chip custom-date" id="customDateBtn"><span>Altra data</span><small id="customDateLabel">Scegli giorno</small><input class="date-picker-native" type="date" id="bookingDate" min="${today()}" value="${today()}" aria-label="Scegli un'altra data"></label></div><div class="booking-current" id="bookingCurrent"></div><div id="slots" class="slots premium-slots"></div><div id="customerFields" class="customer-step hidden"><div class="step-title"><span class="eyebrow">3 · I TUOI DATI</span><strong id="selectedTime"></strong></div><div class="form-grid"><div class="field"><label>Nome e cognome</label><input class="input" id="customerName" autocomplete="name"></div><div class="field"><label>Telefono</label><input class="input" id="customerPhone" inputmode="tel" autocomplete="tel"></div><div class="field full"><label>Email <span class="muted">(facoltativa)</span></label><input class="input" id="customerEmail" type="email" autocomplete="email"></div><div class="field full"><button class="btn primary full-btn" id="confirmBooking">Conferma prenotazione</button></div></div></div></div></section>
    ${c.conventions_enabled?conventionsSection():''}<footer class="center-footer"><div><strong>${esc(c.name)}</strong><span>${esc(c.address||'')}</span></div><div class="row">${c.phone?`<a href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:''}${c.email?`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:''}</div></footer><nav class="customer-mobile-nav"><a href="/">Centri</a><a class="active" href="#book">Prenota</a>${c.conventions_enabled?'<a href="#conventions">Convenzioni</a>':''}</nav></main>`;
  bindPublic(); if(first)loadSlots();
}
function fieldCards(){return state.fields.length?state.fields.map((f,i)=>{const p=fieldPrice(f);return `<button class="field-premium-card selectable ${i===0?'selected':''}" data-book-field="${f.id}"><div class="field-top"><span class="sport-chip">${esc(f.sport)}</span><span class="field-state">Prenotabile</span></div><h3>${esc(f.name)}</h3><p>${esc(f.surface||'Superficie non specificata')} · ${f.indoor?'Coperto':'Scoperto'}</p><div class="field-bottom"><div><strong>${money(p.base)} / ${money(p.shower)}</strong><span>a persona · senza / con doccia · ${f.duration_minutes} min</span>${f.pricing_note?`<small>${esc(f.pricing_note)}</small>`:''}</div><span class="round-action">→</span></div></button>`}).join(''):'<div class="empty">Nessun campo disponibile.</div>'}
function conventionsSection(){const c=state.center;return `<section class="center-section" id="conventions"><div class="convention-box"><div class="convention-copy"><span class="eyebrow">GRUPPI E SQUADRE</span><h2>Convenzioni sportive</h2><p>Richiedi un utilizzo ricorrente del campo. La richiesta non blocca automaticamente gli orari: il gestore ti contatterà per concordare i dettagli.</p><div class="row">${c.whatsapp?`<a class="btn primary" target="_blank" href="https://wa.me/${String(c.whatsapp).replace(/\D/g,'')}?text=${encodeURIComponent('Ciao, vorrei informazioni sulle convenzioni sportive.')}">Parla con il gestore</a>`:''}${c.phone?`<a class="btn" href="tel:${esc(c.phone)}">Chiama</a>`:''}</div></div><form class="convention-form" id="conventionForm"><div class="form-grid"><div class="field"><label>Gruppo / squadra</label><input class="input" name="group_name" required></div><div class="field"><label>Referente</label><input class="input" name="contact_name" required></div><div class="field"><label>Telefono</label><input class="input" name="phone" required></div><div class="field"><label>Campo</label><select class="input" name="field_id"><option value="">Da concordare</option>${state.fields.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="field"><label>Giorni preferiti</label><input class="input" name="preferred_days" placeholder="Es. mercoledì"></div><div class="field"><label>Orario</label><input class="input" name="preferred_times" placeholder="Es. 20:00–21:00"></div><div class="field"><label>Frequenza</label><input class="input" name="frequency" placeholder="Es. ogni settimana"></div><div class="field"><label>Periodo</label><input class="input" name="period_text" placeholder="Es. ottobre–maggio"></div><div class="field full"><label>Note</label><textarea class="input" name="notes" rows="3"></textarea></div><div class="field full"><button class="btn primary full-btn">Invia richiesta</button></div></div></form></div></section>`}
function bindPublic(){
  $$('[data-install]').forEach(b=>b.onclick=installApp);$$('[data-book-field]').forEach(b=>b.onclick=()=>{state.selectedField=state.fields.find(f=>Number(f.id)===Number(b.dataset.bookField));$$('[data-book-field]').forEach(x=>x.classList.toggle('selected',x===b));state.selectedSlot=null;loadSlots();$('#book').scrollIntoView({behavior:'smooth',block:'start'})});
  $$('[data-date]').forEach(b=>b.onclick=()=>{state.selectedDate=b.dataset.date;$('#bookingDate').value=state.selectedDate;$('#customDateBtn').classList.remove('active');$('#customDateLabel').textContent='Scegli giorno';$$('.date-chip[data-date]').forEach(x=>x.classList.toggle('active',x===b));loadSlots()});
  $('#bookingDate').onchange=e=>{if(!e.target.value)return;state.selectedDate=e.target.value;$$('.date-chip[data-date]').forEach(x=>x.classList.remove('active'));$('#customDateBtn').classList.add('active');$('#customDateLabel').textContent=prettyDate(state.selectedDate);loadSlots()};$('#confirmBooking').onclick=confirmBooking;
  $('#conventionForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));try{await api('convention',{method:'POST',body:JSON.stringify({...fd,center_id:state.center.id})});e.currentTarget.reset();toast('Richiesta inviata al gestore')}catch(err){toast(err.message,'error')}})
}
async function loadSlots(){if(!state.selectedField)return;const f=state.selectedField,d=state.selectedDate||today();$('#customerFields').classList.add('hidden');state.selectedSlot=null;$('#bookingCurrent').innerHTML=`<strong>${esc(f.name)}</strong><span>${longDate(d)} · ${priceText(f,d)}</span>${f.pricing_note?`<small>${esc(f.pricing_note)}</small>`:''}`;$('#slots').innerHTML='<div class="slots-label">Caricamento disponibilità…</div>';try{const x=await api(`availability&field_id=${f.id}&date=${d}`);state.selectedField={...f,...x.field};const free=x.slots.filter(s=>s.available).length;$('#slots').innerHTML=`<div class="slots-label">${free?`${free} orari disponibili`:'Nessun orario libero'}</div>${x.slots.map(s=>`<button class="slot" ${s.available?'':'disabled'} data-slot="${s.start}" data-end="${s.end}">${s.start}</button>`).join('')}`;$$('.slot:not(:disabled)').forEach(b=>b.onclick=()=>{$$('.slot').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');state.selectedSlot={start:b.dataset.slot,end:b.dataset.end};const p=fieldPrice(state.selectedField,d);$('#selectedTime').innerHTML=`${esc(f.name)} · ${prettyDate(d)} · ${b.dataset.slot}–${b.dataset.end}<small>${money(p.base)} senza doccia / ${money(p.shower)} con doccia, a persona. Pagamento al gestore.</small>`;$('#customerFields').classList.remove('hidden');$('#customerFields').scrollIntoView({behavior:'smooth',block:'nearest'})})}catch(e){toast(e.message,'error')}}
async function confirmBooking(){if(!state.selectedSlot)return;const payload={field_id:state.selectedField.id,date:state.selectedDate,start_time:state.selectedSlot.start,customer_name:$('#customerName').value.trim(),customer_phone:$('#customerPhone').value.trim(),customer_email:$('#customerEmail').value.trim()};try{const r=await api('booking',{method:'POST',body:JSON.stringify(payload)});showBookingConfirmation(r,payload);await loadSlots()}catch(e){toast(e.message,'error')}}
function showBookingConfirmation(r,p){const c=state.center,f=state.selectedField,m=modal(`<div class="success-mark">✓</div><div class="confirm-copy"><span class="eyebrow">PRENOTAZIONE CONFERMATA</span><h2>Ci vediamo in campo.</h2><p>La prenotazione è stata registrata. Il pagamento avviene direttamente con il gestore.</p></div><div class="confirmation-card"><div><span>Centro</span><strong>${esc(c.name)}</strong></div><div><span>Campo</span><strong>${esc(f.name)}</strong></div><div><span>Quando</span><strong>${prettyDate(p.date)} · ${p.start_time}–${r.end_time}</strong></div><div><span>Tariffa</span><strong>${money(r.price_cents)} / ${money(r.shower_price_cents)} a persona</strong></div><div><span>Riferimento</span><strong>#${r.booking_id}</strong></div></div><div class="row confirm-actions">${c.whatsapp?`<a class="btn primary" target="_blank" href="https://wa.me/${String(c.whatsapp).replace(/\D/g,'')}?text=${encodeURIComponent(`Ciao, ho prenotato ${f.name} il ${p.date} alle ${p.start_time}. Riferimento #${r.booking_id}`)}">WhatsApp centro</a>`:''}${c.phone?`<a class="btn" href="tel:${esc(c.phone)}">Chiama</a>`:''}<button class="btn" data-close>Chiudi</button></div>`,'confirmation-modal');$('[data-close]',m).onclick=()=>m.remove();$('#customerName').value='';$('#customerPhone').value='';$('#customerEmail').value=''}

function renderLogin(){setAccent('#101828');app.innerHTML=`<div class="login-page"><a class="login-back" href="/">← Torna ai centri</a><div class="login-shell"><div class="login-copy"><div class="portal-mark">S</div><span class="eyebrow">AREA RISERVATA</span><h1>Gestisci il centro</h1><p>Un solo accesso: il sistema apre automaticamente il pannello ADMIN o gestore corretto.</p></div><form class="login-card" id="loginForm"><h2>Accedi</h2><p class="muted">Inserisci le credenziali.</p><div class="stack"><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Password</label><input class="input" type="password" name="password" required></div><button class="btn primary full-btn">Accedi</button></div></form></div></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api('login',{method:'POST',body:JSON.stringify(fd)});location.href=r.role==='admin'?'/?view=admin':'/?view=manager'}catch(err){toast(err.message,'error')}}}
async function loadMe(){return (await api('me')).session}
function layout(role,title,content){return `<div class="app-layout"><aside class="sidebar"><div class="side-brand"><div class="logo">S</div><div><strong>Sport Booking</strong><span>${role==='admin'?'ADMIN':'GESTORE'}</span></div></div><nav class="side-nav"><a href="${role==='admin'?'/?view=admin':'/?view=manager'}" class="active">Dashboard</a><a href="/">Apri portale</a><button data-logout>Esci</button></nav></aside><main class="workspace"><div class="workspace-top"><div><span class="eyebrow">${role==='admin'?'PIATTAFORMA':'CENTRO SPORTIVO'}</span><h1>${esc(title)}</h1></div><button class="btn" data-logout>Esci</button></div>${content}</main></div>`}
function bindLogout(){$$('[data-logout]').forEach(b=>b.onclick=async()=>{await api('logout',{method:'POST',body:'{}'});location.href='/'})}

async function loadAdmin(){const me=await loadMe();if(!me||me.role!=='admin')return renderLogin();const [c,m]=await Promise.all([api('admin-centers'),api('admin-managers')]);state.centers=c.centers||[];state.managers=m.managers||[];state.adminStats=c.stats||{};setAccent('#101828');renderAdmin()}
function renderAdmin(){const s=state.adminStats||{};const content=`<div class="row admin-actions"><button class="btn primary" id="newCenter">+ Nuovo centro</button><button class="btn" id="newManager">+ Accesso gestore</button></div><div class="stats admin-stats"><div class="card stat"><span class="muted">Centri attivi</span><strong>${s.centers_active||0}<small> / ${s.centers_total||0}</small></strong></div><div class="card stat"><span class="muted">Campi attivi</span><strong>${s.fields_active||0}</strong></div><div class="card stat"><span class="muted">Prenotazioni mese</span><strong>${s.month_bookings||0}</strong></div><div class="card stat"><span class="muted">Gestori attivi</span><strong>${s.managers_active||0}</strong></div></div><section class="card"><div class="section-head"><div><h2>Centri sportivi</h2><div class="muted">Branding, campi, utilizzo e accessi separati per ogni struttura.</div></div></div><div class="stack">${state.centers.length?state.centers.map(c=>`<div class="admin-center-row"><div class="center-card"><div class="logo">${c.logo_url?`<img src="${esc(c.logo_url)}">`:'S'}</div><div><strong>${esc(c.name)}</strong><div class="muted">${esc(locationLabel(c.address))} · ${c.fields_count} campi · ${c.month_bookings||0} prenotazioni questo mese</div></div></div><div class="spacer"></div><span class="status ${c.active?'confirmed':'cancelled'}">${c.active?'Attivo':'Disattivato'}</span><button class="btn small" data-fields="${c.id}">Gestisci campi</button><a class="btn small" target="_blank" href="/?center=${encodeURIComponent(c.slug)}">Apri app</a><button class="btn small" data-edit-center="${c.id}">Modifica</button></div>`).join(''):'<div class="empty">Nessun centro.</div>'}</div></section><section class="card section"><div class="section-head"><div><h2>Accessi gestori</h2><div class="muted">Gli account vengono creati e assegnati soltanto dalla tua ADMIN.</div></div><button class="btn small primary" id="newManager2">+ Nuovo accesso</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Gestore</th><th>Centro</th><th>Stato</th><th></th></tr></thead><tbody>${state.managers.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="muted">${esc(x.email)}</div></td><td>${esc(x.center_name||'')}</td><td><span class="status ${x.active?'confirmed':'cancelled'}">${x.active?'Attivo':'Disattivato'}</span></td><td><div class="row"><button class="btn small" data-edit-manager="${x.id}">Modifica</button><button class="btn small" data-reset-manager="${x.id}">Password</button></div></td></tr>`).join('')}</tbody></table></div></section>`;app.innerHTML=layout('admin','Centri sportivi',content);bindLogout();$('#newCenter').onclick=()=>centerForm();$('#newManager').onclick=$('#newManager2').onclick=()=>managerForm();$$('[data-edit-center]').forEach(b=>b.onclick=()=>centerForm(state.centers.find(c=>c.id==b.dataset.editCenter)));$$('[data-fields]').forEach(b=>b.onclick=()=>manageCenterFields(state.centers.find(c=>c.id==b.dataset.fields)));$$('[data-edit-manager]').forEach(b=>b.onclick=()=>managerForm(state.managers.find(x=>x.id==b.dataset.editManager)));$$('[data-reset-manager]').forEach(b=>b.onclick=()=>resetManagerPassword(state.managers.find(x=>x.id==b.dataset.resetManager)))}
function managerForm(mgr={}){if(!state.centers.length)return toast('Crea prima almeno un centro','error');const editing=!!mgr.id,m=modal(`<div class="section-head"><h2>${editing?'Modifica accesso gestore':'Nuovo accesso gestore'}</h2><button class="btn small" data-close>Chiudi</button></div><form id="managerForm" class="form-grid"><input type="hidden" name="id" value="${mgr.id||''}"><div class="field full"><label>Centro assegnato</label><select class="input" name="center_id">${state.centers.map(c=>`<option value="${c.id}" ${Number(mgr.center_id)===Number(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Nome gestore</label><input class="input" name="name" value="${esc(mgr.name||'')}" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" value="${esc(mgr.email||'')}" required></div>${editing?'':`<div class="field full"><label>Password iniziale</label><input class="input" name="password" type="password" minlength="6" required></div>`}${editing?`<label class="check"><input type="checkbox" name="active" ${mgr.active?'checked':''}> Accesso attivo</label>`:''}<div class="field full"><button class="btn primary full-btn">${editing?'Salva modifiche':'Crea accesso'}</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();$('#managerForm',m).onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));fd.id=Number(fd.id||0);fd.center_id=Number(fd.center_id);if(editing)fd.active=e.currentTarget.active.checked;try{await api(editing?'admin-manager-update':'admin-manager-create',{method:'POST',body:JSON.stringify(fd)});m.remove();toast('Accesso salvato');loadAdmin()}catch(err){toast(err.message,'error')}}}
function resetManagerPassword(mgr){const m=modal(`<div class="section-head"><div><h2>Nuova password</h2><div class="muted">${esc(mgr.name)}</div></div><button class="btn small" data-close>Chiudi</button></div><form id="resetManagerForm" class="form-grid"><div class="field full"><label>Nuova password</label><input class="input" type="password" name="password" minlength="6" required></div><div class="field full"><button class="btn primary full-btn">Aggiorna</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();$('#resetManagerForm',m).onsubmit=async e=>{e.preventDefault();try{await api('admin-manager-reset-password',{method:'POST',body:JSON.stringify({id:mgr.id,password:new FormData(e.currentTarget).get('password')})});m.remove();toast('Password aggiornata')}catch(err){toast(err.message,'error')}}}
async function uploadMedia(file,input){if(!file)return;const fd=new FormData();fd.append('file',file);try{input.disabled=true;const r=await api('upload-media',{method:'POST',body:fd});input.closest('.media-upload').querySelector('input[type="text"]').value=r.url;toast('Immagine caricata')}catch(e){toast(e.message,'error')}finally{input.disabled=false}}
function centerForm(c={}){const m=modal(`<div class="section-head"><h2>${c.id?'Modifica centro':'Nuovo centro'}</h2><button class="btn small" data-close>Chiudi</button></div><form id="centerForm" class="form-grid"><input type="hidden" name="id" value="${c.id||''}"><div class="field"><label>Nome centro</label><input class="input" name="name" value="${esc(c.name||'')}" required></div><div class="field"><label>Slug</label><input class="input" name="slug" value="${esc(c.slug||'')}" placeholder="campizzi" required></div><div class="field"><label>Colore</label><input class="input color-input" type="color" name="accent_color" value="${c.accent_color||'#111827'}"></div><div class="field"><label>Località / indirizzo</label><input class="input" name="address" value="${esc(c.address||'')}"></div><div class="field media-upload"><label>Logo</label><input class="input" type="text" name="logo_url" value="${esc(c.logo_url||'')}" placeholder="URL o carica file"><input class="input file-input" type="file" accept="image/*" data-upload></div><div class="field media-upload"><label>Copertina</label><input class="input" type="text" name="cover_url" value="${esc(c.cover_url||'')}" placeholder="URL o carica file"><input class="input file-input" type="file" accept="image/*" data-upload></div><div class="field"><label>Telefono</label><input class="input" name="phone" value="${esc(c.phone||'')}"></div><div class="field"><label>WhatsApp</label><input class="input" name="whatsapp" value="${esc(c.whatsapp||'')}"></div><div class="field full"><label>Email</label><input class="input" name="email" value="${esc(c.email||'')}"></div><div class="field full"><label>Descrizione</label><textarea class="input" name="description" rows="3">${esc(c.description||'')}</textarea></div><label class="check"><input type="checkbox" name="conventions_enabled" ${c.conventions_enabled!==0?'checked':''}> Convenzioni</label><label class="check"><input type="checkbox" name="recurring_enabled" ${c.recurring_enabled!==0?'checked':''}> Ricorrenti</label><label class="check"><input type="checkbox" name="active" ${c.active!==0?'checked':''}> Centro attivo</label><div class="field full"><button class="btn primary full-btn">Salva centro</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();$$('[data-upload]',m).forEach(i=>i.onchange=()=>uploadMedia(i.files[0],i));$('#centerForm',m).onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));fd.id=Number(fd.id||0);fd.conventions_enabled=e.currentTarget.conventions_enabled.checked;fd.recurring_enabled=e.currentTarget.recurring_enabled.checked;fd.active=e.currentTarget.active.checked;delete fd.file;try{await api('admin-center-save',{method:'POST',body:JSON.stringify(fd)});m.remove();toast('Centro salvato');loadAdmin()}catch(err){toast(err.message,'error')}}}
async function manageCenterFields(center){try{const d=await api(`admin-fields&center_id=${center.id}`),fields=d.fields||[];const m=modal(`<div class="section-head"><div><h2>Campi · ${esc(center.name)}</h2><div class="muted">Tariffe, orari e disponibilità.</div></div><button class="btn small" data-close>Chiudi</button></div><div class="row" style="margin-bottom:18px"><button class="btn primary" id="addField">+ Nuovo campo</button></div><div class="stack">${fields.length?fields.map(f=>`<div class="admin-center-row"><div><strong>${esc(f.name)}</strong><div class="muted">${esc(f.sport)} · ${money(f.price_cents)} / ${money(f.shower_price_cents)} a persona · ${f.duration_minutes} min</div>${f.pricing_note?`<small class="muted">${esc(f.pricing_note)}</small>`:''}</div><div class="spacer"></div><span class="status ${f.active?'confirmed':'cancelled'}">${f.active?'Attivo':'Disattivato'}</span><button class="btn small" data-edit-field="${f.id}">Modifica</button></div>`).join(''):'<div class="empty">Nessun campo.</div>'}</div>`);$('[data-close]',m).onclick=()=>m.remove();$('#addField',m).onclick=()=>fieldForm(center,{},m);$$('[data-edit-field]',m).forEach(b=>b.onclick=()=>fieldForm(center,fields.find(f=>f.id==b.dataset.editField),m))}catch(e){toast(e.message,'error')}}
function fieldForm(center,f={},parent=null){const editing=!!f.id,m=modal(`<div class="section-head"><div><h2>${editing?'Modifica campo':'Nuovo campo'}</h2><div class="muted">${esc(center.name)}</div></div><button class="btn small" data-close>Chiudi</button></div><form id="fieldForm" class="form-grid"><input type="hidden" name="id" value="${f.id||''}"><input type="hidden" name="center_id" value="${center.id}"><div class="field"><label>Nome campo</label><input class="input" name="name" value="${esc(f.name||'')}" required></div><div class="field"><label>Disciplina</label><input class="input" name="sport" value="${esc(f.sport||'')}" required></div><div class="field"><label>Superficie</label><input class="input" name="surface" value="${esc(f.surface||'')}"></div><div class="field"><label>Durata (min)</label><input class="input" type="number" min="15" step="15" name="duration_minutes" value="${f.duration_minutes||60}"></div><div class="field"><label>€ persona senza doccia</label><input class="input" type="number" step=".01" min="0" name="price_no_shower" value="${f.price_cents!=null?(f.price_cents/100).toFixed(2):''}" required></div><div class="field"><label>€ persona con doccia</label><input class="input" type="number" step=".01" min="0" name="price_shower" value="${f.shower_price_cents!=null?(f.shower_price_cents/100).toFixed(2):''}" required></div><div class="field"><label>Weekend senza doccia € <span class="muted">(facoltativo)</span></label><input class="input" type="number" step=".01" min="0" name="weekend_price_no_shower" value="${f.weekend_price_cents? (f.weekend_price_cents/100).toFixed(2):''}"></div><div class="field"><label>Weekend con doccia € <span class="muted">(facoltativo)</span></label><input class="input" type="number" step=".01" min="0" name="weekend_price_shower" value="${f.weekend_shower_price_cents?(f.weekend_shower_price_cents/100).toFixed(2):''}"></div><div class="field full"><label>Nota tariffa <span class="muted">(facoltativa)</span></label><input class="input" name="pricing_note" value="${esc(f.pricing_note||'')}" placeholder="Es. illuminazione inclusa, promozione feriale..."></div><div class="field"><label>Apertura</label><input class="input" type="time" name="opening_time" value="${f.opening_time||'08:00'}"></div><div class="field"><label>Chiusura</label><input class="input" type="time" name="closing_time" value="${f.closing_time||'23:00'}"></div><label class="check"><input type="checkbox" name="indoor" ${f.indoor?'checked':''}> Campo coperto</label>${editing?`<label class="check"><input type="checkbox" name="active" ${f.active?'checked':''}> Campo attivo e prenotabile</label>`:''}<div class="field full"><button class="btn primary full-btn">${editing?'Salva modifiche':'Crea campo'}</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();$('#fieldForm',m).onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));fd.id=Number(fd.id||0);fd.center_id=Number(fd.center_id);fd.indoor=e.currentTarget.indoor.checked;if(editing)fd.active=e.currentTarget.active.checked;try{await api('admin-field-save',{method:'POST',body:JSON.stringify(fd)});m.remove();parent?.remove();toast('Campo salvato');await loadAdmin();const c=state.centers.find(x=>Number(x.id)===Number(center.id));if(c)manageCenterFields(c)}catch(err){toast(err.message,'error')}}}

async function loadManager(){const me=await loadMe();if(!me||me.role!=='manager')return renderLogin();state.manager=await api('manager-dashboard');state.weekStart=state.weekStart||mondayOf();state.calendarMonth=state.calendarMonth||today().slice(0,7);setAccent(state.manager.center.accent_color);renderManager()}
function monthTitle(ym){const [y,m]=ym.split('-').map(Number);return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(y,m-1,1))}
function shiftMonth(ym,n){const [y,m]=ym.split('-').map(Number),d=new Date(y,m-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function managerCalendarTitle(){return state.calendarView==='month'?monthTitle(state.calendarMonth):`Settimana ${prettyDate(state.weekStart)} – ${prettyDate(addDays(state.weekStart,6))}`}
function conventionsManager(){const d=state.manager;return `<section class="card section"><div class="section-head"><div><h2>Convenzioni</h2><div class="muted">Richieste di squadre e gruppi.</div></div></div><div class="stack">${d.conventions.length?d.conventions.map(x=>`<div class="admin-center-row"><div><strong>${esc(x.group_name)}</strong><div class="muted">${esc(x.contact_name)} · ${esc(x.phone)} · ${esc(x.field_name||'Da concordare')}</div><small>${esc(x.preferred_days)} ${esc(x.preferred_times)} · ${esc(x.frequency)} · ${esc(x.period_text)}</small></div><div class="spacer"></div><select class="input compact" data-conv="${x.id}"><option value="new" ${x.status==='new'?'selected':''}>Nuova</option><option value="negotiating" ${x.status==='negotiating'?'selected':''}>In trattativa</option><option value="accepted" ${x.status==='accepted'?'selected':''}>Accettata</option><option value="rejected" ${x.status==='rejected'?'selected':''}>Rifiutata</option></select></div>`).join(''):'<div class="empty">Nessuna richiesta.</div>'}</div></section>`}
function bookingDetail(id){const b=state.manager.bookings.find(x=>Number(x.id)===id);if(!b)return;const m=modal(`<div class="section-head"><div><h2>${b.status==='blocked'?'Chiusura / blocco':'Prenotazione'}</h2><div class="muted">${prettyDate(b.date)} · ${b.start_time}–${b.end_time}</div></div><button class="btn small" data-close>Chiudi</button></div><div class="confirmation-card"><div><span>Campo</span><strong>${esc(b.field_name)}</strong></div>${b.status!=='blocked'?`<div><span>Cliente</span><strong>${esc(b.customer_name)}</strong></div><div><span>Telefono</span><strong>${esc(b.customer_phone||'—')}</strong></div><div><span>Pagamento</span><strong>${b.payment_status==='paid'?'Pagato':'Da pagare'}</strong></div>`:''}<div><span>Note</span><strong>${esc(b.notes||'—')}</strong></div></div><div class="row confirm-actions">${b.status!=='blocked'?`<button class="btn" id="togglePaid">${b.payment_status==='paid'?'Segna da pagare':'Segna pagato'}</button>`:''}<button class="btn danger" id="cancelBooking">${b.status==='blocked'?'Rimuovi blocco':'Annulla prenotazione'}</button></div>`);$('[data-close]',m).onclick=()=>m.remove();$('#togglePaid',m)?.addEventListener('click',async()=>{await api('manager-booking-status',{method:'POST',body:JSON.stringify({id:b.id,payment_status:b.payment_status==='paid'?'due':'paid'})});m.remove();loadManager()});$('#cancelBooking',m).onclick=async()=>{await api('manager-booking-status',{method:'POST',body:JSON.stringify({id:b.id,status:'cancelled'})});m.remove();loadManager()}}
async function customerHistory(phone){try{const c=state.manager.customers.find(x=>x.customer_phone===phone),d=await api(`manager-customer-history&phone=${encodeURIComponent(phone)}`);const m=modal(`<div class="section-head"><div><h2>${esc(c?.customer_name||'Cliente')}</h2><div class="muted">${esc(phone)} · ${c?.bookings_count||0} prenotazioni totali</div></div><button class="btn small" data-close>Chiudi</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ora</th><th>Campo</th><th>Stato</th></tr></thead><tbody>${d.bookings.map(b=>`<tr><td>${prettyDate(b.date)}</td><td>${b.start_time}–${b.end_time}</td><td>${esc(b.field_name)}</td><td><span class="status ${b.status}">${b.status}</span></td></tr>`).join('')}</tbody></table></div>`);$('[data-close]',m).onclick=()=>m.remove()}catch(e){toast(e.message,'error')}}
function manageBookingsModal(){
  const d=state.manager;
  const normal=d.bookings.filter(b=>b.source!=='recurring'&&b.source!=='block');
  const recurring=d.bookings.filter(b=>b.source==='recurring'&&b.recurring_group);
  const blocks=d.bookings.filter(b=>b.source==='block');
  const groups={};
  recurring.forEach(b=>{(groups[b.recurring_group]??=[]).push(b)});
  const groupList=Object.entries(groups).sort((a,b)=>(a[1][0]?.date||'').localeCompare(b[1][0]?.date||''));
  const active=x=>x.status!=='cancelled';
  const m=modal(`<div class="section-head"><div><h2>Gestione prenotazioni</h2><div class="muted">Prenotazioni singole, serie ricorrenti e chiusure sono gestite separatamente.</div></div><button class="btn small" data-close>Chiudi</button></div>
  <div class="booking-tabs">
    <button class="booking-tab active" data-booking-tab="normal">Singole <span>${normal.filter(active).length}</span></button>
    <button class="booking-tab" data-booking-tab="recurring">Ricorrenti <span>${groupList.filter(([,x])=>x.some(active)).length}</span></button>
    <button class="booking-tab" data-booking-tab="blocks">Chiusure <span>${blocks.filter(active).length}</span></button>
  </div>
  <div class="booking-tab-panel" data-panel="normal">${renderNormalBookings(normal)}</div>
  <div class="booking-tab-panel hidden" data-panel="recurring">${renderRecurringGroups(groupList)}</div>
  <div class="booking-tab-panel hidden" data-panel="blocks">${renderBlockBookings(blocks)}</div>`,'booking-management-modal');
  $('[data-close]',m).onclick=()=>m.remove();
  $$('[data-booking-tab]',m).forEach(btn=>btn.onclick=()=>{
    $$('[data-booking-tab]',m).forEach(x=>x.classList.toggle('active',x===btn));
    $$('[data-panel]',m).forEach(x=>x.classList.toggle('hidden',x.dataset.panel!==btn.dataset.bookingTab));
  });
  $$('[data-open-booking]',m).forEach(b=>b.onclick=()=>bookingDetail(Number(b.dataset.openBooking)));
  $$('[data-cancel-one]',m).forEach(b=>b.onclick=async()=>{
    if(!confirm('Annullare questa prenotazione?'))return;
    await api('manager-booking-bulk-cancel',{method:'POST',body:JSON.stringify({ids:[Number(b.dataset.cancelOne)]})});
    m.remove();toast('Prenotazione annullata');await loadManager();manageBookingsModal();
  });
  $$('[data-cancel-group]',m).forEach(b=>b.onclick=async()=>{
    const group=b.dataset.cancelGroup;
    const items=groups[group]||[];
    const activeCount=items.filter(active).length;
    if(!activeCount)return;
    if(!confirm(`Annullare tutte le ${activeCount} prenotazioni ancora attive di questa serie?`))return;
    const r=await api('manager-booking-bulk-cancel',{method:'POST',body:JSON.stringify({recurring_group:group})});
    m.remove();toast(`${r.updated} prenotazioni della serie annullate`);await loadManager();manageBookingsModal();
  });
  $$('[data-cancel-selected]',m).forEach(b=>b.onclick=async()=>{
    const card=b.closest('.recurring-group-card');
    const ids=$$('input[data-recurring-instance]:checked',card).map(x=>Number(x.value));
    if(!ids.length)return toast('Seleziona almeno una data','error');
    if(!confirm(`Annullare ${ids.length} prenotazioni selezionate?`))return;
    const r=await api('manager-booking-bulk-cancel',{method:'POST',body:JSON.stringify({ids})});
    m.remove();toast(`${r.updated} prenotazioni annullate`);await loadManager();manageBookingsModal();
  });
  $$('[data-remove-block]',m).forEach(b=>b.onclick=async()=>{
    if(!confirm('Rimuovere questa chiusura?'))return;
    await api('manager-booking-bulk-cancel',{method:'POST',body:JSON.stringify({ids:[Number(b.dataset.removeBlock)]})});
    m.remove();toast('Chiusura rimossa');await loadManager();manageBookingsModal();
  });
}
function bookingStateLabel(b){return b.status==='cancelled'?'Annullata':b.status==='blocked'?'Attiva':'Confermata'}
function renderNormalBookings(items){
  const sorted=[...items].sort((a,b)=>(b.date+b.start_time).localeCompare(a.date+a.start_time));
  return sorted.length?`<div class="manage-list">${sorted.map(b=>`<div class="manage-row ${b.status==='cancelled'?'is-cancelled':''}"><div><strong>${prettyDate(b.date)} · ${b.start_time}–${b.end_time}</strong><span>${esc(b.field_name)} · ${esc(b.customer_name||'Cliente')}</span></div><div class="spacer"></div><span class="status ${b.status}">${bookingStateLabel(b)}</span><button class="btn small" data-open-booking="${b.id}">Apri</button>${b.status!=='cancelled'?`<button class="btn small danger" data-cancel-one="${b.id}">Annulla</button>`:''}</div>`).join('')}</div>`:'<div class="empty">Nessuna prenotazione singola.</div>';
}
function renderRecurringGroups(groupList){
  if(!groupList.length)return '<div class="empty">Nessuna prenotazione ricorrente.</div>';
  return `<div class="recurring-groups">${groupList.map(([group,items])=>{
    const sorted=[...items].sort((a,b)=>(a.date+a.start_time).localeCompare(b.date+b.start_time));
    const active=sorted.filter(x=>x.status!=='cancelled'),first=sorted[0];
    const schedules=[...new Set(sorted.map(x=>`${dayNames[new Date(`${x.date}T12:00:00`).getDay()]} ${x.start_time}`))].join(' · ');
    return `<section class="recurring-group-card"><div class="recurring-group-head"><div><span class="eyebrow">SERIE RICORRENTE</span><h3>${esc(first?.customer_name||'Ricorrente')}</h3><p>${esc(first?.field_name||'')} · ${schedules}</p><small>${active.length} attive su ${sorted.length} registrate · ${prettyDate(sorted[0].date)} → ${prettyDate(sorted[sorted.length-1].date)}</small></div>${active.length?`<button class="btn small danger" data-cancel-group="${esc(group)}">Annulla tutta la serie</button>`:'<span class="status cancelled">Serie annullata</span>'}</div>
      <div class="recurring-instance-list">${sorted.map(x=>`<label class="recurring-instance ${x.status==='cancelled'?'is-cancelled':''}"><input type="checkbox" data-recurring-instance value="${x.id}" ${x.status==='cancelled'?'disabled':''}><span><strong>${prettyDate(x.date)} · ${x.start_time}–${x.end_time}</strong><small>${x.status==='cancelled'?'Annullata':x.payment_status==='paid'?'Pagato':'Da pagare'}</small></span><button class="btn tiny" type="button" data-open-booking="${x.id}">Apri</button></label>`).join('')}</div>
      ${active.length?`<div class="recurring-group-actions"><button class="btn danger" data-cancel-selected="${esc(group)}">Annulla date selezionate</button></div>`:''}
    </section>`;
  }).join('')}</div>`;
}
function renderBlockBookings(items){
  const sorted=[...items].sort((a,b)=>(b.date+b.start_time).localeCompare(a.date+a.start_time));
  return sorted.length?`<div class="manage-list">${sorted.map(b=>`<div class="manage-row ${b.status==='cancelled'?'is-cancelled':''}"><div><strong>${prettyDate(b.date)} · ${b.start_time}–${b.end_time}</strong><span>${esc(b.field_name)} · ${esc(b.notes||'Chiusura / manutenzione')}</span></div><div class="spacer"></div><span class="status ${b.status}">${b.status==='cancelled'?'Rimossa':'Attiva'}</span>${b.status!=='cancelled'?`<button class="btn small danger" data-remove-block="${b.id}">Rimuovi</button>`:''}</div>`).join('')}</div>`:'<div class="empty">Nessuna chiusura registrata.</div>';
}

function renderManager(){const d=state.manager,s=d.stats||{},repeat=d.customers.filter(c=>Number(c.bookings_count)>1).length;const content=`<div class="manager-toolbar"><div class="row"><button class="btn primary" id="manualBooking">+ Prenotazione</button><button class="btn" id="manageBookings">Gestisci prenotazioni</button><button class="btn" id="blockTime">+ Chiusura / blocco</button>${d.center.recurring_enabled?'<button class="btn" id="recurringBooking">+ Ricorrente</button>':''}</div><a class="btn" target="_blank" href="/?center=${encodeURIComponent(d.center.slug)}">Apri app centro</a></div><div class="stats"><div class="card stat"><span class="muted">Oggi</span><strong>${s.today_bookings||0}</strong></div><div class="card stat"><span class="muted">Prenotazioni mese</span><strong>${s.month_bookings||0}</strong></div><div class="card stat"><span class="muted">Ore occupate mese</span><strong>${s.month_hours||0}</strong></div><div class="card stat"><span class="muted">Clienti ricorrenti</span><strong>${repeat}</strong></div></div><section class="card calendar-card"><div class="section-head calendar-head"><div><h2>Calendario</h2><div class="muted calendar-period">${managerCalendarTitle()}</div></div><div class="calendar-controls"><div class="calendar-view-toggle"><button class="calendar-view-btn ${state.calendarView==='week'?'active':''}" data-calendar-view="week">Settimana</button><button class="calendar-view-btn ${state.calendarView==='month'?'active':''}" data-calendar-view="month">Mese</button></div><div class="row calendar-nav"><button class="btn small" id="prevCalendar">←</button><button class="btn small" id="todayCalendar">Oggi</button><button class="btn small" id="nextCalendar">→</button></div></div></div><div id="managerCalendar">${state.calendarView==='month'?monthCalendar():weekCalendar()}</div></section><div class="manager-grid"><section class="card"><div class="section-head"><div><h2>Clienti abituali</h2><div class="muted">Storico basato sul numero di telefono.</div></div></div><div class="customer-list">${d.customers.length?d.customers.slice(0,12).map(c=>`<button class="customer-row" data-customer="${esc(c.customer_phone)}"><div><strong>${esc(c.customer_name)}</strong><span>${esc(c.customer_phone)}</span></div><div><strong>${c.bookings_count}</strong><span>prenotazioni</span></div></button>`).join(''):'<div class="empty">Nessun cliente ancora.</div>'}</div></section><section class="card"><div class="section-head"><div><h2>Andamento</h2><div class="muted">Ultimi 90 giorni.</div></div></div><div class="insight-list"><div><span>Giorno più richiesto</span><strong>${d.top_day?dayNames[Number(d.top_day.dow)]:'—'}</strong></div><div><span>Fascia più richiesta</span><strong>${d.top_hour?`${String(d.top_hour.hour).padStart(2,'0')}:00`:'—'}</strong></div><div><span>Da incassare</span><strong>${s.due_count||0}</strong></div><div><span>Blocchi futuri</span><strong>${s.future_blocks||0}</strong></div></div></section></div>${d.center.conventions_enabled?conventionsManager():''}`;app.innerHTML=layout('manager',d.center.name,content);bindLogout();bindManager()}
function weekCalendar(){const d=state.manager,days=Array.from({length:7},(_,i)=>addDays(state.weekStart,i));return `<div class="week-calendar">${days.map(day=>{const items=d.bookings.filter(b=>b.date===day&&b.status!=='cancelled');return `<div class="calendar-day"><button class="calendar-day-head calendar-day-button" data-calendar-day="${day}"><strong>${prettyDate(day)}</strong><span>${items.length}</span></button><div class="calendar-events">${items.length?items.map(b=>calendarEvent(b)).join(''):'<div class="calendar-empty">Libero</div>'}</div></div>`}).join('')}</div>`}
function calendarEvent(b,compact=false){return `<div class="calendar-event ${b.status==='blocked'?'blocked':''} ${compact?'compact':''}" data-booking="${b.id}"><b>${b.start_time}–${b.end_time}</b><strong>${esc(b.field_name)}</strong><span>${b.status==='blocked'?'Chiusura / blocco':esc(b.customer_name)}</span>${!compact&&b.status!=='blocked'?`<small>${b.payment_status==='paid'?'Pagato':'Da pagare'}</small>`:''}</div>`}
function monthCalendar(){const d=state.manager,[year,month]=state.calendarMonth.split('-').map(Number),first=new Date(year,month-1,1),lastDay=new Date(year,month,0).getDate();let firstDow=first.getDay();firstDow=firstDow===0?7:firstDow;const start=new Date(year,month-1,1-(firstDow-1));const cells=Array.from({length:42},(_,i)=>{const x=new Date(start);x.setDate(start.getDate()+i);return isoDate(x)});const currentPrefix=state.calendarMonth;return `<div class="month-weekdays">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-calendar">${cells.map(day=>{const items=d.bookings.filter(b=>b.date===day&&b.status!=='cancelled'),inMonth=day.startsWith(currentPrefix),isToday=day===today();return `<button class="month-day ${inMonth?'':'outside'} ${isToday?'today':''}" data-calendar-day="${day}" type="button"><div class="month-day-head"><strong>${Number(day.slice(-2))}</strong>${items.length?`<span>${items.length}</span>`:''}</div><div class="month-day-events">${items.slice(0,3).map(b=>`<div class="month-event ${b.status==='blocked'?'blocked':''}"><b>${b.start_time}</b><span>${esc(b.field_name)}</span></div>`).join('')}${items.length>3?`<small>+${items.length-3} altri</small>`:''}</div></button>`}).join('')}</div>`}
function calendarDayModal(day){const items=state.manager.bookings.filter(b=>b.date===day&&b.status!=='cancelled');const m=modal(`<div class="section-head"><div><span class="eyebrow">${longDate(day)}</span><h2>${items.length?`${items.length} ${items.length===1?'evento':'eventi'}`:'Nessun evento'}</h2></div><button class="btn small" data-close>Chiudi</button></div><div class="day-detail-list">${items.length?items.map(b=>`<button class="day-detail-event ${b.status==='blocked'?'blocked':''}" data-day-booking="${b.id}"><div><strong>${b.start_time}–${b.end_time}</strong><span>${esc(b.field_name)}</span></div><div><b>${b.status==='blocked'?'Chiusura / blocco':esc(b.customer_name)}</b>${b.status!=='blocked'?`<small>${b.payment_status==='paid'?'Pagato':'Da pagare'}</small>`:''}</div><span>→</span></button>`).join(''):'<div class="empty">La giornata è completamente libera.</div>'}</div><button class="btn primary full-btn" id="dayNewBooking">+ Prenotazione per questo giorno</button>`);$('[data-close]',m).onclick=()=>m.remove();$$('[data-day-booking]',m).forEach(x=>x.onclick=()=>{m.remove();bookingDetail(Number(x.dataset.dayBooking))});$('#dayNewBooking',m).onclick=()=>{m.remove();bookingModal(false,day)}}
function bindManager(){const d=state.manager;$('#manualBooking').onclick=()=>bookingModal(false);$('#manageBookings').onclick=manageBookingsModal;$('#blockTime').onclick=blockModal;$('#recurringBooking')?.addEventListener('click',recurringModal);$$('[data-calendar-view]').forEach(b=>b.onclick=()=>{state.calendarView=b.dataset.calendarView;if(state.calendarView==='month')state.calendarMonth=(state.weekStart||today()).slice(0,7);else state.weekStart=mondayOf(`${state.calendarMonth}-01`);renderManager()});$('#prevCalendar').onclick=()=>{if(state.calendarView==='month')state.calendarMonth=shiftMonth(state.calendarMonth,-1);else state.weekStart=addDays(state.weekStart,-7);renderManager()};$('#nextCalendar').onclick=()=>{if(state.calendarView==='month')state.calendarMonth=shiftMonth(state.calendarMonth,1);else state.weekStart=addDays(state.weekStart,7);renderManager()};$('#todayCalendar').onclick=()=>{state.weekStart=mondayOf();state.calendarMonth=today().slice(0,7);renderManager()};$$('[data-calendar-day]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-booking]'))return;calendarDayModal(b.dataset.calendarDay)});$$('[data-customer]').forEach(b=>b.onclick=()=>customerHistory(b.dataset.customer));$$('[data-booking]').forEach(b=>b.onclick=e=>{e.stopPropagation();bookingDetail(Number(b.dataset.booking))});$$('[data-conv]').forEach(s=>s.onchange=async()=>{await api('manager-convention-status',{method:'POST',body:JSON.stringify({id:Number(s.dataset.conv),status:s.value})});toast('Stato aggiornato')})}
function bookingModal(_,presetDate=today()){const d=state.manager,m=modal(`<div class="section-head"><h2>Nuova prenotazione</h2><button class="btn small" data-close>Chiudi</button></div><form id="bookingForm" class="form-grid"><div class="field full"><label>Campo</label><select class="input" name="field_id">${d.fields.filter(f=>f.active).map(f=>`<option value="${f.id}">${esc(f.name)} · ${esc(f.sport)}</option>`).join('')}</select></div><div class="field"><label>Cliente</label><input class="input" name="customer_name" required></div><div class="field"><label>Telefono</label><input class="input" name="customer_phone"></div><div class="field"><label>Data</label><input class="input" type="date" name="date" value="${presetDate}" required></div><div class="field"><label>Dalle</label><input class="input" type="time" name="start_time" required></div><div class="field"><label>Alle <span class="muted">(automatico se vuoto)</span></label><input class="input" type="time" name="end_time"></div><div class="field"><label>Pagamento</label><select class="input" name="payment_status"><option value="due">Da pagare</option><option value="paid">Pagato</option></select></div><div class="field full"><label>Note</label><textarea class="input" name="notes"></textarea></div><div class="field full"><button class="btn primary full-btn">Salva prenotazione</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();$('#bookingForm',m).onsubmit=async e=>{e.preventDefault();try{await api('manager-booking',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});m.remove();toast('Prenotazione salvata');loadManager()}catch(err){toast(err.message,'error')}}}
function blockModal(){const d=state.manager,m=modal(`<div class="section-head"><div><h2>Chiusura / manutenzione</h2><div class="muted">Puoi bloccare uno o tutti i campi anche per più giorni consecutivi.</div></div><button class="btn small" data-close>Chiudi</button></div><form id="blockForm" class="form-grid"><div class="field full"><label>Campo</label><select class="input" name="field_id"><option value="">Tutti i campi</option>${d.fields.filter(f=>f.active).map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="field"><label>Dal</label><input class="input" type="date" name="date_from" value="${today()}" required></div><div class="field"><label>Al</label><input class="input" type="date" name="date_to" value="${today()}" required></div><label class="check full"><input type="checkbox" name="full_day" checked> Intera giornata</label><div class="field block-time-field"><label>Dalle</label><input class="input" type="time" name="start_time"></div><div class="field block-time-field"><label>Alle</label><input class="input" type="time" name="end_time"></div><div class="field full"><label>Motivo</label><input class="input" name="notes" placeholder="Manutenzione, evento, chiusura..."></div><div class="field full"><button class="btn primary full-btn">Crea chiusura</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();const form=$('#blockForm',m),toggleTimes=()=>{$$('.block-time-field',m).forEach(x=>x.classList.toggle('hidden',form.full_day.checked))};toggleTimes();form.full_day.onchange=toggleTimes;form.date_from.onchange=()=>{if(!form.date_to.value||form.date_to.value<form.date_from.value)form.date_to.value=form.date_from.value;form.date_to.min=form.date_from.value};form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));fd.full_day=e.currentTarget.full_day.checked;if(fd.date_to<fd.date_from)return toast('La data finale non può essere precedente a quella iniziale','error');if(!fd.full_day&&(!fd.start_time||!fd.end_time))return toast('Indica orario di inizio e fine','error');try{const r=await api('manager-block',{method:'POST',body:JSON.stringify(fd)});m.remove();toast(`${r.created.length} blocchi creati${r.conflicts.length?` · ${r.conflicts.length} conflitti saltati`:''}`);loadManager()}catch(err){toast(err.message,'error')}}}
function recurringModal(){const d=state.manager,m=modal(`<div class="section-head"><div><h2>Prenotazione ricorrente</h2><div class="muted">Aggiungi più giorni della settimana, ognuno con il proprio orario.</div></div><button class="btn small" data-close>Chiudi</button></div><form id="recurringForm" class="form-grid"><div class="field full"><label>Campo</label><select class="input" name="field_id">${d.fields.filter(f=>f.active).map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="field"><label>Gruppo / cliente</label><input class="input" name="customer_name" required></div><div class="field"><label>Telefono</label><input class="input" name="customer_phone"></div><div class="field"><label>Dal</label><input class="input" type="date" name="start_date" value="${today()}" required></div><div class="field"><label>Al</label><input class="input" type="date" name="end_date" required></div><div class="field full"><div class="schedule-head"><div><label>Giorni e orari</label><small class="muted">Esempio: martedì 19:00 + giovedì 20:00. La fine viene calcolata dalla durata del campo.</small></div><button class="btn small" type="button" id="addRecurringDay">+ Aggiungi giorno</button></div><div id="recurringSchedules" class="recurring-schedules"></div></div><div class="field"><label>Pagamento</label><select class="input" name="payment_status"><option value="due">Da pagare</option><option value="paid">Pagato</option></select></div><div class="field full"><label>Note</label><textarea class="input" name="notes"></textarea></div><div class="field full"><button class="btn primary full-btn">Controlla date e conflitti</button></div></form>`);$('[data-close]',m).onclick=()=>m.remove();const box=$('#recurringSchedules',m);let rowId=0;const addRow=(weekday=2,start='')=>{const row=document.createElement('div');row.className='recurring-schedule-row';row.dataset.row=String(++rowId);row.innerHTML=`<div class="field"><label>Giorno</label><select class="input schedule-weekday">${dayNames.map((x,i)=>`<option value="${i}" ${i===weekday?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Ora inizio</label><input class="input schedule-time" type="time" value="${start}" required></div><button class="btn small danger schedule-remove" type="button" title="Rimuovi">×</button>`;box.append(row);$('.schedule-remove',row).onclick=()=>{if($$('.recurring-schedule-row',box).length===1)return toast('Deve rimanere almeno un giorno','error');row.remove()}};addRow(2,'19:00');$('#addRecurringDay',m).onclick=()=>addRow(4,'20:00');const form=$('#recurringForm',m);form.start_date.onchange=()=>{if(!form.end_date.value||form.end_date.value<form.start_date.value)form.end_date.value=form.start_date.value;form.end_date.min=form.start_date.value};form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget));const schedules=$$('.recurring-schedule-row',box).map(row=>({weekday:Number($('.schedule-weekday',row).value),start_time:$('.schedule-time',row).value})).filter(x=>x.start_time);if(!schedules.length)return toast('Aggiungi almeno un giorno con orario','error');fd.schedules=schedules;if(!fd.end_date)return toast('Indica la data finale','error');if(fd.end_date<fd.start_date)return toast('La data finale non può essere precedente a quella iniziale','error');try{const r=await api('manager-recurring-preview',{method:'POST',body:JSON.stringify(fd)});showRecurringPreview(m,fd,r)}catch(err){toast(err.message,'error')}}}
function showRecurringPreview(parent,payload,r){const m=modal(`<div class="section-head"><div><h2>Controllo ricorrenza</h2><div class="muted">${r.available.length} slot liberi · ${r.conflicts.length} in conflitto</div></div><button class="btn small" data-close>Chiudi</button></div>${r.conflicts.length?`<div class="notice error"><strong>Slot già occupati:</strong><div class="conflict-list">${r.conflicts.map(x=>`<span>${prettyDate(x.date)} · ${x.start_time}–${x.end_time}</span>`).join('')}</div></div>`:''}<div class="recurring-dates"><p class="muted">Deseleziona eventuali appuntamenti che non vuoi creare.</p>${r.available.length?r.available.map(x=>`<label class="check recurring-date"><input type="checkbox" checked value="${x.date}|${x.start_time}"> ${prettyDate(x.date)} · ${x.start_time}–${x.end_time}</label>`).join(''):'<div class="empty">Nessuno slot disponibile nel periodo selezionato.</div>'}</div><button class="btn primary full-btn" id="confirmRecurring" ${r.available.length?'':'disabled'}>Crea ${r.available.length} prenotazioni</button>`);$('[data-close]',m).onclick=()=>m.remove();$('#confirmRecurring',m).onclick=async()=>{const skip_slots=$$('.recurring-date input:not(:checked)',m).map(x=>x.value);try{const out=await api('manager-recurring',{method:'POST',body:JSON.stringify({...payload,skip_slots})});m.remove();parent.remove();toast(`${out.created.length} prenotazioni ricorrenti create${out.conflicts.length?` · ${out.conflicts.length} conflitti saltati`:''}`);loadManager()}catch(e){toast(e.message,'error')}}}

(async()=>{try{if(view==='login')renderLogin();else if(view==='admin')await loadAdmin();else if(view==='manager')await loadManager();else if(centerSlug)await loadPublic();else await loadHome()}catch(e){app.innerHTML=`<div class="login-wrap"><div class="login-card"><h1>Errore</h1><p class="muted">${esc(e.message)}</p><a class="btn" href="/">Torna alla Home</a></div></div>`}})();
